  List<ScorePoint> Daily(){var result=new List<ScorePoint>();if(data==null)return result;foreach(int m in ScoreModes())foreach(var group in data.Battles.Where(b=>b.Mode==m).GroupBy(b=>new{Source=b.ViewSourceKey,Date=Day(b.Start)}).OrderBy(g=>g.Key.Date)){if((dateFrom.Checked&&group.Key.Date<dateFrom.Value.Date)||(dateTo.Checked&&group.Key.Date>dateTo.Value.Date))continue;var valid=group.Where(b=>b.DetailStatus=="ok"&&b.ScoreAfter.HasValue).OrderBy(b=>b.Start).ThenBy(b=>b.Id).ToList();if(valid.Count==0)continue;result.Add(new ScorePoint{Date=group.Key.Date,Source=group.Key.Source,Mode=m,Before=valid[0].ScoreBefore,After=valid.Last().ScoreAfter.Value,Time=valid.Last().Start,Recorded=valid.Count,Total=group.Count()});}return result;}
  void UpdateScores(){if(scoreMode.Items.Count==0)return;var days=Daily();scoreCanvas.Modes=ScoreModes();scoreCanvas.Sources=data!=null&&data.IsAggregate?data.ViewSources.ToDictionary(Merge.Key,x=>x.Name+" / "+x.SeasonName+" / "+x.GameCode):new Dictionary<string,string>();if(scoreGranularity.SelectedIndex==0)scoreCanvas.Points=days;else scoreCanvas.Points=data==null?new List<ScorePoint>():data.Battles.Where(b=>ScoreModes().Contains(b.Mode)&&b.DetailStatus=="ok"&&b.ScoreAfter.HasValue&&(!dateFrom.Checked||Day(b.Start)>=dateFrom.Value.Date)&&(!dateTo.Checked||Day(b.Start)<=dateTo.Value.Date)).Select(b=>new ScorePoint{Source=b.ViewSourceKey,Mode=b.Mode,Time=b.Start,Date=Day(b.Start),Before=b.ScoreBefore,After=b.ScoreAfter.Value}).ToList();var table=new DataTable();foreach(string c in new[]{"账号 / 赛季","日期（北京时间）","模式","首记录前","末记录后","增减","有分数 / 总记录"})table.Columns.Add(c);foreach(var p in days.OrderByDescending(p=>p.Date))table.Rows.Add(scoreCanvas.Sources.ContainsKey(p.Source)?scoreCanvas.Sources[p.Source]:data.Name+" / "+data.SeasonName,p.Date.ToString("yyyy-MM-dd"),Stats.Label(p.Mode),RecordCanvas.Score(p.Before),p.After.ToString(),p.Before.HasValue?(p.After-p.Before).ToString():"未知",p.Recorded+" / "+p.Total);scoreTable.DataSource=table;SizeChart();scoreCanvas.Invalidate();}
  void SizeChart(){scoreCanvas.Width=Math.Max(250,chartScroll.ClientSize.Width-22);scoreCanvas.Height=Math.Max(200,(int)(240*uiScale)*scoreCanvas.SeriesCount);}
  void ExportScores(){RequireData();using(var d=new SaveFileDialog{Filter="CSV 表格|*.csv",FileName="星之翼-"+data.SeasonName+"-分数日期.csv"})if(d.ShowDialog(this)==DialogResult.OK){var rows=new List<string>{"账号 / 赛季,日期（北京时间）,模式,首记录前,末记录后,实际记录分差,有分数场数,已取得总场数"};foreach(var p in Daily())rows.Add(string.Join(",",new[]{"\""+(scoreCanvas.Sources.ContainsKey(p.Source)?scoreCanvas.Sources[p.Source]:data.Name+" / "+data.SeasonName).Replace("\"","\"\"")+"\"",p.Date.ToString("yyyy-MM-dd"),Stats.Label(p.Mode),p.Before.HasValue?p.Before.ToString():"",p.After.ToString(),p.Before.HasValue?(p.After-p.Before).ToString():"",p.Recorded.ToString(),p.Total.ToString()}));File.WriteAllText(d.FileName,string.Join("\r\n",rows),new UTF8Encoding(true));}}
  void BackupAll(){var snaps=ReadSources();if(snaps.Count==0)throw new Exception("请先导入战绩。");using(var d=new SaveFileDialog{Filter="JSON 数据|*.json",FileName="星之翼-全部赛季备份.json"})if(d.ShowDialog(this)==DialogResult.OK)File.WriteAllText(d.FileName,J.Json.Serialize(new SnapshotArchive{Snapshots=snaps}),new UTF8Encoding(false));}
 }
}
